                        <tr>
                            <td class="center"><?php echo $i + 1; ?></td>
                            <td class="center"><?php echo $escape($nim); ?></td>
                            <td class="name"><?php echo $escape($siswa['nama'] ?? ''); ?></td>
                            <td class="center"><?php echo array_key_exists('skor_akhir', $nilai) ? $escape(number_format((float)$nilai['skor_akhir'], 2, ',', '.')) : ''; ?></td>
                            <td class="center"><?php echo $escape($nilai['nilai_huruf'] ?? ''); ?></td>
                            <td class="center"><?php echo isset($nilai['angka_mutu']) ? $escape($nilai['angka_mutu']) : ''; ?></td>
                            <td contenteditable="true" data-edit-key="ket-<?php echo $escape(rawurlencode($nim)); ?>"></td>
                        </tr>
                    <?php endforeach; else: ?>
                        <tr><td colspan="7" class="empty-note">Belum ada mahasiswa pada prodi, semester, dan kelas ini. Tambahkan data terlebih dahulu melalui halaman Data Mahasiswa.</td></tr>
                    <?php endif; ?>
                    </tbody>
                </table>
            </div>
            <section class="grading-scale selectable-element" id="examScaleBlock" data-type="Pedoman predikat" onclick="pilihElemen(event,this)" aria-label="Pedoman nilai">
                <table>
                    <thead><tr><th data-edit-key="scale-score-head" contenteditable="true">Skor</th><th data-edit-key="scale-letter-head" contenteditable="true">Nilai Huruf</th><th data-edit-key="scale-mutu-head" contenteditable="true">Mutu</th><th data-edit-key="scale-predicate-head" contenteditable="true">Predikat</th></tr></thead>
                    <tbody>
                        <tr><td contenteditable="true" data-edit-key="scale-a-score">80-100</td><td contenteditable="true" data-edit-key="scale-a-letter">A</td><td contenteditable="true" data-edit-key="scale-a-mutu">4</td><td contenteditable="true" data-edit-key="scale-a-predicate">Sangat Baik</td></tr>
                        <tr><td contenteditable="true" data-edit-key="scale-b-score">66-79</td><td contenteditable="true" data-edit-key="scale-b-letter">B</td><td contenteditable="true" data-edit-key="scale-b-mutu">3</td><td contenteditable="true" data-edit-key="scale-b-predicate">Baik</td></tr>
                        <tr><td contenteditable="true" data-edit-key="scale-c-score">56-65</td><td contenteditable="true" data-edit-key="scale-c-letter">C</td><td contenteditable="true" data-edit-key="scale-c-mutu">2</td><td contenteditable="true" data-edit-key="scale-c-predicate">Cukup</td></tr>
                        <tr><td contenteditable="true" data-edit-key="scale-d-score">46-55</td><td contenteditable="true" data-edit-key="scale-d-letter">D</td><td contenteditable="true" data-edit-key="scale-d-mutu">1</td><td contenteditable="true" data-edit-key="scale-d-predicate">Kurang</td></tr>
                        <tr><td contenteditable="true" data-edit-key="scale-e-score">0-45</td><td contenteditable="true" data-edit-key="scale-e-letter">E</td><td contenteditable="true" data-edit-key="scale-e-mutu">0</td><td contenteditable="true" data-edit-key="scale-e-predicate">Sangat Kurang</td></tr>
                    </tbody>
                </table>
            </section>
            <?php if (!empty($saved_grade['saved_at'])): ?>
                <p class="saved-note">Nilai dikirim dari rekap absen: <?php echo $escape(date('d-m-Y H:i', strtotime($saved_grade['saved_at']))); ?></p>
            <?php endif; ?>
        </section>
    </main>

    <script>
        const storageKey = <?php echo json_encode($local_key, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_AMP); ?>;
        const paper = document.getElementById('paperSheet');
        let zoomLevel = 1;
        let selectedElement = null;
        function toggleInspectorPanel() {
            const panel = document.getElementById('inspectorPanel');
            panel.classList.toggle('minimized');
            document.getElementById('inspectorToggleBtn').classList.toggle('show', panel.classList.contains('minimized'));
        }
        function updateZoom() {
            paper.style.zoom = String(zoomLevel);
            document.getElementById('zoomLabel').textContent = Math.round(zoomLevel * 100) + '%';
        }
        function ubahZoom(delta) { zoomLevel = Math.max(.6, Math.min(1.6, Math.round((zoomLevel + delta) * 10) / 10)); updateZoom(); }
        function resetZoom() { zoomLevel = 1; updateZoom(); }

        function readSavedEdits() {
            try {
                const saved = JSON.parse(localStorage.getItem(storageKey) || '{}');
                document.querySelectorAll('[data-edit-key]').forEach(el => {
                    const key = el.dataset.editKey;
                    if (Object.prototype.hasOwnProperty.call(saved.text || {}, key)) el.textContent = saved.text[key];
                });
                ['logoLeftSlot', 'logoRightSlot'].forEach(id => { if (saved.logos && saved.logos[id]) setLogo(id, saved.logos[id]); });
                Object.entries(saved.positions || {}).forEach(([id, transform]) => { const el = document.getElementById(id); if (el && el.matches('.selectable-element')) el.style.transform = transform; });
            } catch (error) { console.warn('Pengaturan lembar ujian lokal tidak dapat dibaca.', error); }
        }
        function saveEdits() {
            try {
                const saved = JSON.parse(localStorage.getItem(storageKey) || '{}');
                saved.text = saved.text || {};
                document.querySelectorAll('[data-edit-key]').forEach(el => { saved.text[el.dataset.editKey] = el.textContent; });
                localStorage.setItem(storageKey, JSON.stringify(saved));
            } catch (error) { alert('Penyimpanan edit teks penuh. Hapus beberapa data situs dari pengaturan browser lalu coba lagi.'); }
        }
        function setLogo(slotId, src) {
            const slot = document.getElementById(slotId), img = slot.querySelector('img'), icon = slot.querySelector('i'), remove = slot.querySelector('.logo-remove');
            img.src = src; img.hidden = false; icon.hidden = true; remove.hidden = src === img.dataset.defaultSrc; slot.classList.add('has-logo');
        }
        function saveLogo(slotId, src) {
            try {
                const saved = JSON.parse(localStorage.getItem(storageKey) || '{}');
                saved.logos = saved.logos || {}; saved.logos[slotId] = src;
                localStorage.setItem(storageKey, JSON.stringify(saved));
            } catch (error) { alert('Ukuran logo terlalu besar untuk disimpan di browser. Gunakan gambar yang lebih kecil.'); }
        }
        document.querySelectorAll('.logo-slot').forEach(slot => {
            const input = slot.querySelector('input[type="file"]');
            const remove = slot.querySelector('.logo-remove');
            const image = slot.querySelector('img'); image.dataset.defaultSrc = image.src;
            slot.classList.add('has-logo');
            input.addEventListener('change', event => {
                const file = event.target.files && event.target.files[0];
                if (!file) return;
                if (!file.type.startsWith('image/')) { alert('Pilih berkas gambar untuk logo.'); return; }
                const reader = new FileReader();
                reader.onload = () => { setLogo(slot.id, reader.result); saveLogo(slot.id, reader.result); };
                reader.readAsDataURL(file);
            });
            remove.addEventListener('click', event => {
                event.preventDefault(); event.stopPropagation();
                const image = slot.querySelector('img');
                if (image.dataset.defaultSrc) { setLogo(slot.id, image.dataset.defaultSrc); remove.hidden = true; }
                else { image.removeAttribute('src'); image.hidden = true; slot.querySelector('i').hidden = false; slot.classList.remove('has-logo'); }
                input.value = '';
                try { const saved = JSON.parse(localStorage.getItem(storageKey) || '{}'); if (saved.logos) delete saved.logos[slot.id]; localStorage.setItem(storageKey, JSON.stringify(saved)); } catch (error) {}
            });
        });
        function pilihElemen(event, el) {
            event.stopPropagation();
            document.querySelectorAll('.selectable-element.selected').forEach(node => node.classList.remove('selected'));
            selectedElement = el;
            el.classList.add('selected');
            document.getElementById('activeElementLabel').textContent = el.dataset.type || 'Elemen';
            const container = document.getElementById('inspectorTextContainer');
            container.replaceChildren();
            const editables = el.querySelectorAll('[contenteditable="true"]');
            if (!editables.length) { container.textContent = 'Elemen ini tidak memiliki teks yang dapat diedit.'; return; }
            editables.forEach((editable, index) => {
                const input = document.createElement('input');
                input.type = 'text'; input.value = editable.textContent; input.setAttribute('aria-label', 'Teks ' + (index + 1));
                input.addEventListener('input', () => { editable.textContent = input.value; saveEdits(); });
                container.appendChild(input);
            });
        }
        document.addEventListener('click', event => {
            if (!event.target.closest('.selectable-element') && !event.target.closest('.inspector-panel')) {
                document.querySelectorAll('.selectable-element.selected').forEach(node => node.classList.remove('selected'));
                selectedElement = null;
                document.getElementById('activeElementLabel').textContent = 'Pilih elemen di lembar kerja...';
                document.getElementById('inspectorTextContainer').innerHTML = '<div style="font-size:11px;color:var(--muted);">Klik blok pada lembar untuk mengedit teksnya di sini.</div>';
            }
        });
        function simpanPosisi() {
            const positions = {};
            document.querySelectorAll('.selectable-element[id]').forEach(el => { if (el.style.transform) positions[el.id] = el.style.transform; });
            try { const saved = JSON.parse(localStorage.getItem(storageKey) || '{}'); saved.positions = positions; localStorage.setItem(storageKey, JSON.stringify(saved)); } catch (error) {}
        }
        function ubahPosisiAktif(axis, delta) {
            if (!selectedElement) return;
            const readPosition = el => { const m = (el.style.transform || '').match(/translate\(\s*([-\d.]+)px\s*,\s*([-\d.]+)px\s*\)/); return m ? [parseFloat(m[1]), parseFloat(m[2])] : [0, 0]; };
            const moving = axis === 'y' ? [selectedElement, ...Array.from(selectedElement.parentElement.children).filter(el => {
                if (el === selectedElement || !el.matches('.selectable-element')) return false;
                const a = selectedElement.getBoundingClientRect(), b = el.getBoundingClientRect();
                const overlap = Math.max(0, Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top));
                return b.width > 0 && b.height > 0 && overlap >= Math.min(a.height, b.height) * .45;
            })] : [selectedElement];
            moving.forEach(el => { let [x,y] = readPosition(el); if (axis === 'x') x += delta; else y += delta; el.style.transform = `translate(${x}px, ${y}px)`; });
            simpanPosisi();
        }
        function resetPosisiAktif() { if (selectedElement) { selectedElement.style.transform = 'translate(0px, 0px)'; simpanPosisi(); } }
        document.addEventListener('keydown', event => {
            if (!selectedElement || !['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key)) return;
            if (event.target.closest && event.target.closest('input,textarea,select,button,a')) return;
            event.preventDefault(); const step = event.shiftKey ? 5 : 1;
            if (event.key === 'ArrowUp') ubahPosisiAktif('y',-step);
            if (event.key === 'ArrowDown') ubahPosisiAktif('y',step);
            if (event.key === 'ArrowLeft') ubahPosisiAktif('x',-step);
            if (event.key === 'ArrowRight') ubahPosisiAktif('x',step);
        });
        document.addEventListener('input', event => { if (event.target.matches('[contenteditable="true"]')) saveEdits(); });
        readSavedEdits();
        updateZoom();
    </script>
</body>
</html>
